package com.hotelmanagement.hms.maintenance.model; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="maintenance_tickets") public class MaintenanceTicket extends com.hotelmanagement.hms.shared.model.BranchEntity { @Column(name="room_id") UUID roomId; @Column(columnDefinition="text") String issue; @Enumerated(EnumType.STRING) MaintenancePriority priority; @Enumerated(EnumType.STRING) MaintenanceStatus status; @Column(name="assigned_user_id") UUID assignedUserId; @Column(name="opened_by") UUID openedBy; @Column(name="resolved_at") Instant resolvedAt; protected MaintenanceTicket(){} public static MaintenanceTicket create(UUID h,UUID b,UUID room,String issue,MaintenancePriority p,UUID actor){var e=new MaintenanceTicket();e.hotelId=h;e.branchId=b;e.roomId=room;e.issue=issue;e.priority=p;e.status=MaintenanceStatus.OPEN;e.openedBy=actor;return e;} public UUID getRoomId(){return roomId;} public String getIssue(){return issue;} public MaintenancePriority getPriority(){return priority;} public MaintenanceStatus getStatus(){return status;} public Instant getResolvedAt(){return resolvedAt;} public void transition(MaintenanceStatus s){if(status==MaintenanceStatus.RESOLVED||status==MaintenanceStatus.CANCELLED)throw new IllegalStateException("Ticket is closed.");status=s;if(s==MaintenanceStatus.RESOLVED)resolvedAt=Instant.now();} }
